const TemperatureChart = ({
  item
}) => {
  const frame = useCurrentFrame();
  const {
    fps
  } = useVideoConfig();
  const props = item.props || {};
  const title = props.title || 'RAINFALL TRENDS';
  const subtitle = props.subtitle || 'Monthly Average Rainfall (mm)';
  const bgStart = props.bgStart || '#001518';
  const bgEnd = props.bgEnd || '#133b40';
  const lineColor = props.lineColor || '#00c1a9';
  const dataValues = [-3, 1, 9, 18, 24, 29, 32, 31, 24, 15, 6, -1];
  const months = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
  const DESIGN_WIDTH = 1920;
  const DESIGN_HEIGHT = 1080;
  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);
  const safeFps = fps || 30;
  const ML = 220,
    MR = 180,
    MT = 340,
    MB = 220;
  const CW = DESIGN_WIDTH - ML - MR;
  const CH = DESIGN_HEIGHT - MT - MB;
  const Y_MIN = -10,
    Y_MAX = 40;
  const getX = i => i / (dataValues.length - 1) * CW;
  const getY = v => CH - (v - Y_MIN) / (Y_MAX - Y_MIN) * CH;
  const generatePath = pts => {
    let d = `M ${getX(0)} ${getY(pts[0])}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const x1 = getX(i),
        y1 = getY(pts[i]);
      const x2 = getX(i + 1),
        y2 = getY(pts[i + 1]);
      const cp1x = x1 + (x2 - x1) / 3;
      const cp2x = x2 - (x2 - x1) / 3;
      d += ` C ${cp1x} ${y1}, ${cp2x} ${y2}, ${x2} ${y2}`;
    }
    return d;
  };
  const pathD = generatePath(dataValues);
  const lineProgress = spring({
    frame,
    fps: safeFps,
    config: {
      damping: 22,
      stiffness: 50,
      mass: 1.5
    }
  });
  const titleSpring = spring({
    frame,
    fps: safeFps,
    config: {
      damping: 22,
      stiffness: 90
    }
  });
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1]);
  const titleY = interpolate(titleSpring, [0, 1], [-40, 0]);
  const gridVals = [-10, 0, 10, 20, 30, 40];
  const maxVal = Math.max(...dataValues);
  const minVal = Math.min(...dataValues);
  return <div style={{
    position: 'absolute',
    top: 0,
    left: 0,
    width: DESIGN_WIDTH,
    height: DESIGN_HEIGHT,
    background: `linear-gradient(135deg, ${bgStart} 0%, ${bgEnd} 100%)`,
    transform: `scale(${scale})`,
    transformOrigin: 'top left',
    overflow: 'hidden',
    fontFamily: "'Inter', sans-serif",
    color: '#cfecd7'
  }}>
      <div style={{
      position: 'absolute',
      top: 0,
      left: 0,
      right: 0,
      height: 3,
      background: `linear-gradient(90deg, transparent, ${lineColor}, transparent)`,
      opacity: titleOpacity
    }} />

      <div style={{
      position: 'absolute',
      top: 80,
      width: '100%',
      textAlign: 'center',
      opacity: titleOpacity,
      transform: `translateY(${titleY}px)`
    }}>
        <div style={{
        fontSize: 72,
        fontWeight: 900,
        letterSpacing: '0.08em',
        textTransform: 'uppercase',
        textShadow: `0 0 40px ${lineColor}88`
      }}>{title}</div>
        <div style={{
        fontSize: 28,
        fontWeight: 300,
        marginTop: 14,
        opacity: 0.7,
        letterSpacing: '0.12em'
      }}>{subtitle}</div>
      </div>

      <svg style={{
      position: 'absolute',
      top: MT,
      left: ML
    }} width={CW} height={CH} overflow="visible">
        <defs>
          <linearGradient id="lineGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#4cb158" />
            <stop offset="50%" stopColor={lineColor} />
            <stop offset="100%" stopColor="#c39a00" />
          </linearGradient>
          <filter id="glowTemp">
            <feGaussianBlur stdDeviation="4" result="blur" />
            <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
          <clipPath id="lineClip">
            <rect x={0} y={-60} width={CW * lineProgress} height={CH + 120} />
          </clipPath>
        </defs>

        {/* Grid lines */}
        {gridVals.map((val, i) => {
        const y = getY(val);
        const op = interpolate(frame, [8 + i * 3, 26 + i * 3], [0, 0.28], {
          extrapolateRight: 'clamp'
        });
        return <g key={val} opacity={op}>
              <line x1={0} y1={y} x2={CW} y2={y} stroke="#cfecd7" strokeWidth={val === 0 ? 1.5 : 1} />
              <text x={-16} y={y + 6} fill="#cfecd7" fontSize={20} fontFamily="'IBM Plex Mono', monospace" textAnchor="end" opacity={3}>{val}°</text>
            </g>;
      })}

        {/* X labels */}
        {months.map((m, i) => {
        const x = getX(i);
        const op = interpolate(frame, [20 + i * 2, 36 + i * 2], [0, 0.65], {
          extrapolateRight: 'clamp'
        });
        return <text key={m} x={x} y={CH + 48} fill="#cfecd7" fontSize={18} fontFamily="'IBM Plex Mono', monospace" textAnchor="middle" opacity={op}>{m}</text>;
      })}

        {/* Area fill */}
        <path d={`${pathD} L ${getX(dataValues.length - 1)} ${CH} L ${getX(0)} ${CH} Z`} fill={`url(#lineGrad)`} opacity={0.07} clipPath="url(#lineClip)" />

        {/* Main line */}
        <path d={pathD} fill="none" stroke="url(#lineGrad)" strokeWidth={6} strokeLinecap="round" clipPath="url(#lineClip)" filter="url(#glowTemp)" />

        {/* Data points */}
        {dataValues.map((v, i) => {
        const tp = i / (dataValues.length - 1);
        const vis = lineProgress >= tp - 0.04;
        const s = spring({
          frame: Math.max(0, frame - tp * 45),
          fps: safeFps,
          config: {
            stiffness: 140,
            damping: 12
          }
        });
        const isExtrema = v === maxVal || v === minVal;
        return vis ? <g key={i} transform={`translate(${getX(i)}, ${getY(v)})`}>
              <circle r={isExtrema ? 10 : 6} fill={lineColor} style={{
            transform: `scale(${s})`,
            transformOrigin: '0px 0px'
          }} filter="url(#glowTemp)" />
              {isExtrema && <text y={v < 0 ? 38 : -22} fill="#fff" fontSize={28} fontWeight={700} textAnchor="middle" fontFamily="'IBM Plex Mono', monospace" opacity={s}>{v}°C</text>}
            </g> : null;
      })}
      </svg>

      <div style={{
      position: 'absolute',
      bottom: 0,
      left: 0,
      right: 0,
      height: 2,
      background: `linear-gradient(90deg, transparent, ${lineColor}88, transparent)`,
      opacity: titleOpacity
    }} />
    </div>;
};

