  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);
  const safeFps = fps || 30;
  const outDuration = 22;
  const outStartFrame = durationInFrames - outDuration;
  const slideIn = spring({
    frame,
    fps: safeFps,
    config: {
      damping: 20,
      stiffness: 100,
      mass: 1
    },
    from: -500,
    to: 40
  });
  const outProgress = interpolate(frame, [outStartFrame, outStartFrame + outDuration], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.in(Easing.cubic)
  });
  const slideOut = interpolate(outProgress, [0, 1], [40, -500]);
  const slideX = frame >= outStartFrame ? slideOut : slideIn;
  const wobbleRotation = Math.sin(frame / 20) * 0.1;
  const textStartFrame = 20;
  const nameOpacity = interpolate(frame, [textStartFrame, textStartFrame + 15], [0, 1], {
    extrapolateRight: 'clamp'
  });
