    height: `${STRIP_H}px`,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'flex-start',
    position: 'relative',
    zIndex: 1,
    backgroundImage: 'linear-gradient(178deg, #fff 0%, #f4f4f4 100%)',
    clipPath: `polygon(8px 0%, ${STRIP_W}px 6px, ${STRIP_W - 8}px ${STRIP_H - 6}px, 0px ${STRIP_H}px)`,
    boxSizing: 'border-box',
    overflow: 'hidden'
  };
  const logoContainerStyle = {
