    backgroundColor: accentColor,
    zIndex: 2,
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    clipPath: 'polygon(20% 0%, 90% 10%, 100% 80%, 80% 100%, 10% 90%, 0% 20%)',
    transform: 'rotate(-5deg)'
  };
  const LogoIcon = () => <svg width="30" height="30" viewBox="0 0 100 100" style={{
