const TakeawayOverlayBaked = ({
  item
}) => {
  const frame = useCurrentFrame();
  const {
    fps,
    durationInFrames
  } = useVideoConfig();
  const titleText = "Takeaway";
  const bodyText = "Grow your listener base — don't rely on playlists alone";
  const accentColor = "#ffffff";
  const textColor = "#ffffff";
  const titleFontFamily = "Inter";
  const bodyFontFamily = "Inter";
  const transparentBackground = true;
  const DESIGN_WIDTH = 1200;
  const DESIGN_HEIGHT = 300;
  const scale = Math.min((item?.width || DESIGN_WIDTH) / DESIGN_WIDTH, (item?.height || DESIGN_HEIGHT) / DESIGN_HEIGHT);
  const TITLE_IN_START = 0;
  const TITLE_IN_END = 20;
  const LINE_START = 18;
  const LINE_END = 58;
  const LINE_MAX_W = 270; // 与标题文字等宽
  const BODY_START = 34;
  const LETTER_STAGGER = 0.9;
  const LETTER_DUR = 7;
  const FADE_OUT_START = durationInFrames - 18;
  const FADE_OUT_END = durationInFrames - 2;
  const globalOpacity = interpolate(frame, [Math.max(0, FADE_OUT_START), Math.max(1, FADE_OUT_END)], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });
  const titleProgress = interpolate(frame, [TITLE_IN_START, TITLE_IN_END], [0, 1], {
    easing: Easing.bezier(0.25, 1, 0.5, 1),
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });
  const titleOpacity = titleProgress;
  const titleBlur = interpolate(titleProgress, [0, 1], [14, 0]);
  const tg = titleProgress;
  const titleShadow = [`0 0 4px rgba(255,255,255,${0.95 * tg})`, `0 0 12px rgba(255,255,255,${0.8 * tg})`, `0 0 28px rgba(255,255,255,${0.55 * tg})`, `0 0 56px rgba(255,255,255,${0.3 * tg})`].join(',');
  const lineProgress = interpolate(frame, [LINE_START, LINE_END], [0, 1], {
    easing: Easing.bezier(0.16, 1, 0.3, 1),
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });
  const lineW = lineProgress * LINE_MAX_W;
  const lineGlowPeak = interpolate(frame, [LINE_START, LINE_END, LINE_END + 15], [0, 1, 0.65], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });
  const lineVisible = frame >= LINE_START;
  const svgH = 44;
  const cy = svgH / 2;

  // 左端宽（两点），右端尖（一点）
  const triPoints = (w, hL) => {
    if (w <= 0) return `0,${cy} 0,${cy} 0,${cy}`;
    return `0,${cy - hL} ${w},${cy} 0,${cy + hL}`;
  };
  const hexToRgb = hex => {
    const h = (hex || '#874cff').replace('#', '');
    return {
      r: parseInt(h.slice(0, 2), 16),
      g: parseInt(h.slice(2, 4), 16),
      b: parseInt(h.slice(4, 6), 16)
    };
  };
  const {
    r,
    g: gc,
    b
  } = hexToRgb(accentColor);
  const ac = `${r},${gc},${b}`;
  const rawWords = (bodyText || '').split(' ');
  const rootStyle = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: DESIGN_WIDTH,
    height: DESIGN_HEIGHT,
    transform: `scale(${scale})`,
    transformOrigin: 'top left',
    backgroundColor: transparentBackground ? 'transparent' : 'rgba(10,10,18,0.82)',
    padding: '36px 48px',
    boxSizing: 'border-box',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'flex-start',
    alignItems: 'flex-start',
    opacity: globalOpacity
  };
  const titleStyle = {
    fontFamily: titleFontFamily,
    fontSize: 52,
    fontWeight: 700,
    color: textColor,
    margin: 0,
    letterSpacing: '0.01em',
    lineHeight: 1.15,
    whiteSpace: 'nowrap',
    opacity: titleOpacity,
    filter: `blur(${titleBlur}px)`,
    textShadow: titleShadow
  };
  const lineSvgWrap = {
    marginTop: 4,
    marginBottom: 8,
    flexShrink: 0,
    opacity: lineVisible ? 1 : 0,
    display: 'block',
    overflow: 'visible'
  };
  const bodyContainerStyle = {
    position: 'relative',
    width: '100%',
    lineHeight: 1.55
  };
  let letterIdx = 0;
  const wordNodes = rawWords.map((word, wi) => {
    const wordLetters = word.split('').map(ch => {
      const gi = letterIdx++;
      const start = BODY_START + gi * LETTER_STAGGER;
      const end = start + LETTER_DUR;
      const lp = interpolate(frame, [start, end], [0, 1], {
        easing: Easing.bezier(0.22, 1, 0.36, 1),
        extrapolateLeft: 'clamp',
        extrapolateRight: 'clamp'
      });
      const lY = interpolate(lp, [0, 1], [-9, 0]);
      const lBlur = interpolate(lp, [0, 1], [3, 0]);
      const g = lp;
      const ls = [`0 0 3px rgba(255,255,255,${0.98 * g})`, `0 0 9px rgba(255,255,255,${0.85 * g})`, `0 0 20px rgba(255,255,255,${0.65 * g})`, `0 0 40px rgba(255,255,255,${0.38 * g})`, `0 0 72px rgba(255,255,255,${0.18 * g})`].join(',');
      return <span key={gi} style={{
        display: 'inline-block',
        opacity: lp,
        transform: `translateY(${lY}px)`,
        verticalAlign: 'baseline',
        fontFamily: bodyFontFamily,
        fontSize: 34,
        fontWeight: 300,
        color: textColor,
        filter: `blur(${lBlur}px)`,
        textShadow: ls,
        whiteSpace: 'pre'
      }}>{ch}</span>;
    });
    let spaceNode = null;
    if (wi < rawWords.length - 1) {
      const si = letterIdx++;
      const sp = interpolate(frame, [BODY_START + si * LETTER_STAGGER, BODY_START + si * LETTER_STAGGER + LETTER_DUR], [0, 1], {
        extrapolateLeft: 'clamp',
        extrapolateRight: 'clamp'
      });
      spaceNode = <span key={`sp-${wi}`} style={{
        display: 'inline-block',
        width: '0.28em',
        opacity: sp
      }} />;
    }
    return <span key={`w-${wi}`} style={{
      display: 'inline-block',
      whiteSpace: 'nowrap'
    }}>
        {wordLetters}{spaceNode}
      </span>;
  });
  return <div style={rootStyle}>
      <div style={titleStyle}>{titleText}</div>

      <svg width={LINE_MAX_W} height={svgH} viewBox={`0 0 ${LINE_MAX_W} ${svgH}`} style={lineSvgWrap} overflow="visible">
        <polygon points={triPoints(lineW, 18)} fill={`rgba(${ac},${0.45 * lineGlowPeak})`} style={{
        filter: 'blur(8px)'
      }} />
        <polygon points={triPoints(lineW, 10)} fill={`rgba(${ac},${0.7 * lineGlowPeak})`} style={{
        filter: 'blur(3px)'
      }} />
        <polygon points={triPoints(lineW, 2.5)} fill={`rgba(${ac},0.95)`} />
        <polygon points={triPoints(lineW, 0.8)} fill={`rgba(255,255,255,${0.85 * lineProgress})`} />
      </svg>

      <div style={bodyContainerStyle}>
        <div style={{
        position: 'relative',
        width: '100%',
        lineHeight: 1.55,
        color: textColor
      }}>
          {wordNodes}
        </div>
      </div>
    </div>;
};

