const TheCollective = ({
  item
}) => {
  const frame = useCurrentFrame();
  const {
    fps
  } = useVideoConfig();
  const props = item.props || {};
  const titleText = props.titleText;
  const m1Name = props.m1Name;
  const m1Role = props.m1Role;
  const m1Image = props.m1Image;
  const m2Name = props.m2Name;
  const m2Role = props.m2Role;
  const m2Image = props.m2Image;
  const m3Name = props.m3Name;
  const m3Role = props.m3Role;
  const m3Image = props.m3Image;
  const fontFamily = props.fontFamily;
  const bgColor = props.bgColor;
  const transparentBackground = props.transparentBackground;
  const safeFps = fps || 30;
  const safeSpring = (delay = 0, config = {
    damping: 15
  }) => {
    return spring({
      frame: Math.max(0, frame - delay),
      fps: safeFps,
      config
    });
  };
  const titleY = interpolate(frame, [0, 20], [50, 0], {
    extrapolateRight: 'clamp'
  });
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: 'clamp'
  });
  const m1Scale = safeSpring(24, {
    damping: 15
  });
  const m1Opacity = interpolate(frame, [24, 34], [0, 1], {
    extrapolateRight: 'clamp'
  });
  const m2Scale = safeSpring(54, {
    damping: 15
  });
  const m2Opacity = interpolate(frame, [54, 64], [0, 1], {
    extrapolateRight: 'clamp'
  });
  const m3Scale = safeSpring(84, {
    damping: 15
  });
  const m3Opacity = interpolate(frame, [84, 94], [0, 1], {
    extrapolateRight: 'clamp'
  });
  const b1x = 1920 / 2 + Math.sin(frame / 40) * 600;
  const b1y = 1080 / 2 + Math.cos(frame / 45) * 300;
  const b2x = 1920 / 4 + Math.cos(frame / 30) * 400;
  const b2y = 1080 / 3 + Math.sin(frame / 35) * 400;
  const b3x = 1920 * 0.75 + Math.sin(frame / 50) * 500;
  const b3y = 1080 * 0.75 + Math.cos(frame / 30) * 400;
  const b4x = 1920 / 2 + Math.cos(frame / 60) * 400;
  const b4y = 1080 / 2 + Math.sin(frame / 40) * 500;
  const backgroundColor = transparentBackground ? 'transparent' : bgColor;
  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor,
    fontFamily,
    color: 'white',
    overflow: 'hidden'
  };
  const titleStyle = {
    position: 'absolute',
    top: 150,
    left: 150,
    opacity: titleOpacity,
    transform: `translateY(${titleY}px)`,
    zIndex: 1
  };
  const titleHeadingStyle = {
    fontSize: 64,
    fontStyle: 'italic',
    fontWeight: 900,
    margin: 0,
    textShadow: '0 4px 20px rgba(0,0,0,0.3)'
  };
  const membersContainerStyle = {
    position: 'absolute',
    top: 380,
    left: 0,
    width: '100%',
    display: 'flex',
    justifyContent: 'center',
    gap: 120,
    zIndex: 1
  };
  const memberContainerStyle = {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center'
  };
  const circleStyle = {
    width: 320,
    height: 320,
    borderRadius: '50%',
    border: '4px solid rgba(255,255,255,0.8)',
    overflow: 'hidden',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: 'rgba(255,255,255,0.05)',
    boxShadow: '0 10px 30px rgba(0,0,0,0.4)'
  };
  const imageStyle = {
    width: '100%',
    height: '100%',
    objectFit: 'cover'
  };
  const nameStyle = {
    fontSize: 40,
    fontStyle: 'italic',
    fontWeight: 800,
    margin: '40px 0 10px 0',
    textAlign: 'center',
    textShadow: '0 4px 15px rgba(0,0,0,0.3)'
  };
  const roleStyle = {
    fontSize: 22,
    fontWeight: 400,
    margin: 0,
    opacity: 0.9,
    textAlign: 'center',
    textShadow: '0 4px 15px rgba(0,0,0,0.3)'
  };
  const member1Transform = `scale(${m1Scale})`;
  const member2Transform = `scale(${m2Scale})`;
  const member3Transform = `scale(${m3Scale})`;
  const bgContainerStyle = {
    position: 'absolute',
    inset: 0,
    zIndex: 0,
    overflow: 'hidden',
    backgroundColor: bgColor
  };
  const renderBlob = (color, x, y, size) => {
    const left = x - size / 2;
    const topPos = y - size / 2;
    const background = `radial-gradient(circle, ${color} 0%, transparent 60%)`;
    return <div style={{
      position: 'absolute',
      left,
      top: topPos,
      width: size,
      height: size,
      background,
      borderRadius: '50%',
      opacity: 0.8
    }} />;
  };
  return <div style={rootStyle}>
      {!transparentBackground && <div style={bgContainerStyle}>
          {renderBlob('#0079cc', b1x, b1y, 1200)}
          {renderBlob('#006a82', b2x, b2y, 1400)}
          {renderBlob('#00a2a2', b3x, b3y, 1500)}
          {renderBlob('#005b7d', b4x, b4y, 1600)}
        </div>}

      <div style={titleStyle}>
        <h1 style={titleHeadingStyle}>{titleText}</h1>
      </div>

      <div style={membersContainerStyle}>
        <div style={{
        ...memberContainerStyle,
        transform: member1Transform,
        opacity: m1Opacity
      }}>
          <div style={circleStyle}>
            {m1Image ? <Img src={m1Image} style={imageStyle} /> : null}
          </div>
          <h2 style={nameStyle}>{m1Name}</h2>
          <p style={roleStyle}>{m1Role}</p>
        </div>

        <div style={{
        ...memberContainerStyle,
        transform: member2Transform,
        opacity: m2Opacity
      }}>
          <div style={circleStyle}>
            {m2Image ? <Img src={m2Image} style={imageStyle} /> : null}
          </div>
          <h2 style={nameStyle}>{m2Name}</h2>
          <p style={roleStyle}>{m2Role}</p>
        </div>

        <div style={{
        ...memberContainerStyle,
        transform: member3Transform,
        opacity: m3Opacity
      }}>
          <div style={circleStyle}>
            {m3Image ? <Img src={m3Image} style={imageStyle} /> : null}
          </div>
          <h2 style={nameStyle}>{m3Name}</h2>
          <p style={roleStyle}>{m3Role}</p>
        </div>
      </div>
    </div>;
};

