      display: 'flex',
      alignItems: 'center',
      paddingLeft: 10,
      boxSizing: 'border-box',
      overflow: 'hidden'
    }}>
          <span style={{
        fontSize: 32,
        fontWeight: '700',
        color: mainColor,
        whiteSpace: 'nowrap',
        letterSpacing: 0.5,
        lineHeight: 1
      }}>{displayedMain}</span>
        </div>}
      {lineW > 1 && <div style={{
      position: 'absolute',
      top: LINE_TOP,
      left: 48,
      height: 1.5,
      width: lineW,
      background: `linear-gradient(to right, ${lineColor} 0%, rgba(153,153,153,0) 100%)`
    }} />}
      {subBgW > 1 && <div style={{
      position: 'absolute',
      top: SUB_TOP,
      left: BG_LEFT,
      width: subBgW,
      height: SUB_H,
      backgroundColor: bgColor,
      WebkitMaskImage: subMask,
      maskImage: subMask,
      display: 'flex',
      alignItems: 'center',
      paddingLeft: 10,
      boxSizing: 'border-box',
      overflow: 'hidden'
    }}>
          <span style={{
        fontSize: 20,
        fontStyle: 'italic',
        color: subColor,
        whiteSpace: 'nowrap',
        lineHeight: 1
      }}>{displayedSub}</span>
        </div>}
      <div style={{
      position: 'absolute',
      top: blueBallY,
      left: blueBallX,
      width: BALL,
      height: BALL,
      borderRadius: '50%',
      backgroundColor: blueBallColor,
      opacity: blueBallOpacity,
      zIndex: 10
    }} />
      <div style={{
      position: 'absolute',
      top: redBallY,
      left: redBallX,
      width: BALL,
      height: BALL,
      borderRadius: '50%',
      backgroundColor: redBallColor,
      opacity: redBallOpacity,
      zIndex: 10
    }} />
    </div>;
};

