  const pos = String(p.position || 'bottom-right');
  const R = Math.min(300, Math.max(110, Number(p.size) || 165));
  const left = pos.indexOf('left') >= 0;
  const topPos = pos.indexOf('top') >= 0;
  const cx = left ? M + R : W - M - R;
  const cy = topPos ? M + R : H - M - R;
  const title = p.title == null ? '' : String(p.title);
  const subtitle = p.subtitle == null ? '' : String(p.subtitle);
  const sealText = p.sealText == null ? '' : String(p.sealText).slice(0, 4);
  const enter = spring({
    frame,
    fps,
    config: {
      damping: 15,
      stiffness: 115
    }
  });
  const popIn = spring({
    frame: frame - 7,
    fps,
    config: {
      damping: 12,
      stiffness: 135
    }
  });
  const exit = interpolate(frame, [durationInFrames - 12, durationInFrames], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
