  const hole = `radial-gradient(circle ${R}px at ${cx}px ${cy}px, transparent ${R - 1}px, #000 ${R}px)`;
  const titleX = left ? cx + R + 110 : 170;
  return <AbsoluteFill style={{
    opacity: exit
  }}>
      <AbsoluteFill style={{
      WebkitMaskImage: hole,
      maskImage: hole,
      opacity: enter
